$ErrorActionPreference = "Stop"

$USERNAME = gh api user -q .login
$REPO = "$USERNAME/ncmp"

Write-Host "Configuring for repo: $REPO"

Write-Host "Setting Secrets..."
gh secret set MUSIC_U -b "" --repo $REPO
gh secret set CSRF -b "c410160b1e17a70dd689839777db61be" --repo $REPO
gh secret set WAIT_TIME_MIN -b "20" --repo $REPO
gh secret set WAIT_TIME_MAX -b "45" --repo $REPO

Write-Host "Enabling Workflows..."
gh workflow enable auto_score.yml --repo $REPO
gh workflow list --repo $REPO

Write-Host "Triggering workflow for the first time..."
gh workflow run auto_score.yml --repo $REPO

Write-Host "Done! Successfully configured GitHub Actions."
